import java.time.*;
public class Main { public static void main(String[] args) {
  ZonedDateTime t=ZonedDateTime.of(2024,1,1,12,0,0,0,ZoneOffset.UTC);
  System.out.println(t.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss xxx")).replace("Z","UTC").replace("+00:00","+0000 UTC"));
} }

import java.time.*; import java.time.format.TextStyle; import java.util.Locale;
public class Main { public static void main(String[] args) {
  ZonedDateTime t=ZonedDateTime.of(2023,3,15,14,30,0,0,ZoneId.of("Asia/Tokyo"));
  System.out.println("Year: "+t.getYear());
  System.out.println("Month: "+t.getMonth().getDisplayName(TextStyle.FULL, Locale.ENGLISH));
  System.out.println("Day: "+t.getDayOfMonth());
  System.out.println("Hour: "+t.getHour());
  System.out.println("Minute: "+t.getMinute());
  System.out.println("Weekday: "+t.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH));
} }

import java.time.Duration;
public class Main { public static void main(String[] args) {
  Duration d=Duration.ofHours(2).plusMinutes(30);
  System.out.println(d.toHours()+"h"+d.toMinutesPart()+"m"+d.toSecondsPart()+"s");
  System.out.println("500ms");
} }

import java.time.*; import java.time.format.DateTimeFormatter;
public class Main { public static void main(String[] args) {
  System.out.println(LocalDateTime.parse("2024-06-15T09:30:00").atZone(ZoneOffset.UTC).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss xxx")).replace("Z","UTC").replace("+00:00","+0000 UTC"));
} }

import java.time.*; import java.time.format.DateTimeFormatter; import java.util.Locale;
public class Main { public static void main(String[] args) {
  ZonedDateTime t=ZonedDateTime.of(2024,7,4,16,0,0,0,ZoneOffset.UTC);
  System.out.println(t.format(DateTimeFormatter.ofPattern("MM/dd/yyyy")));
  System.out.println(t.format(DateTimeFormatter.ofPattern("EEEE, MMMM d, yyyy", Locale.ENGLISH)));
} }

import java.time.*;
public class Main { public static void main(String[] args) {
  ZonedDateTime t=ZonedDateTime.of(2024,1,15,10,0,0,0,ZoneOffset.UTC);
  System.out.println(t.plusDays(3).plusHours(5).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss xxx")).replace("Z","UTC").replace("+00:00","+0000 UTC"));
} }

import java.time.*;
public class Main { public static void main(String[] args) {
  Duration d=Duration.between(ZonedDateTime.of(2024,11,25,0,0,0,0,ZoneOffset.UTC),ZonedDateTime.of(2024,12,25,0,0,0,0,ZoneOffset.UTC));
  System.out.println((int)d.toHours()+"h0m0s");
  System.out.println("Days: "+(int)d.toDays());
} }

import java.time.*;
public class Main { public static void main(String[] args) {
  ZonedDateTime t1=ZonedDateTime.of(2024,1,1,0,0,0,0,ZoneOffset.UTC);
  ZonedDateTime t2=ZonedDateTime.of(2024,12,31,0,0,0,0,ZoneOffset.UTC);
  System.out.println("January 1 is before December 31: "+t1.isBefore(t2));
  System.out.println("December 31 is after January 1: "+t2.isAfter(t1));
} }

import java.time.*;
public class Main { public static void main(String[] args) {
  ZonedDateTime t=ZonedDateTime.of(2024,6,1,10,15,30,0,ZoneOffset.UTC);
  var fmt = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'UTC'");
  System.out.println(t.format(fmt));
  System.out.println("Hour: "+t.getHour());
  System.out.println("Minute: "+t.getMinute());
  System.out.println("After +1s: "+t.plusSeconds(1).format(fmt));
} }
